-- Synthetic development fixtures only; every mutation rolls back. Migration 19.
begin;
create temp table author_checks(name text primary key);
grant select,insert on author_checks to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'FAILED %',label; end if; insert into pg_temp.author_checks values(label); end $$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$ declare caught text; begin begin execute sql; exception when others then get stacked diagnostics caught=returned_sqlstate; end; perform pg_temp.ok(caught=code,label||coalesce(' got '||caught,' no error')); end $$;
create function pg_temp.claim(n integer) returns void language sql as $$ select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true) $$;
create function pg_temp.definition() returns jsonb language sql as $$ select '{"title":"Synthetic atomic builder","description":null,"durationMinutes":1,"maxAttempts":2,"isPublished":false,"questions":[{"type":"MCQ","text":"Synthetic question","imageUrl":null,"choices":["Correct","Wrong"],"correctChoice":0,"points":2}]}'::jsonb $$;
-- The legacy builder's save and clone are closed to clients (20261114120000_exams.sql, owner's answer 2). These wrappers run the same definers
-- as the owner with the caller's claims, so the fixtures still build legacy papers and every authorization check inside still applies.
create function pg_temp.legacy_save(p_offering uuid,p_schedule uuid,p_at timestamptz,p_def jsonb) returns uuid language sql security definer set search_path='' as $$select private.save_exam_definition(p_offering,p_schedule,p_at,p_def)$$;
create function pg_temp.legacy_save_v2(p_offering uuid,p_schedule uuid,p_at timestamptz,p_def jsonb) returns uuid language sql security definer set search_path='' as $$select private.save_exam_definition_v2(p_offering,p_schedule,p_at,p_def)$$;
create function pg_temp.legacy_clone(p_schedule uuid) returns uuid language sql security definer set search_path='' as $$select private.clone_exam_schedule(p_schedule)$$;
set local role anon;
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',null,null,pg_temp.definition())$q$,'42501','Anonymous builder denied');
select pg_temp.denied($q$select public.get_exam_definition(gen_random_uuid())$q$,'42501','Anonymous definition denied');
reset role;select pg_temp.claim(5);set local role authenticated;
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',null,null,pg_temp.definition())$q$,'42501','Student builder denied');
reset role;select pg_temp.claim(3);set local role authenticated;
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',null,null,pg_temp.definition())$q$,'42501','Other tenant owner denied');
reset role;select pg_temp.claim(1);set local role authenticated;
select pg_temp.denied($q$select public.save_exam_definition('60000000-0000-0000-0000-000000000001',null,null,pg_temp.definition())$q$,'42501','The closed legacy builder refuses even the owner');
select set_config('author.schedule',pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',null,null,pg_temp.definition())::text,true);
select pg_temp.ok((public.get_exam_definition(current_setting('author.schedule')::uuid)->>'title')='Synthetic atomic builder','Owner creates complete draft');
select pg_temp.ok((select count(*)=1 from public.offering_assessments where id=current_setting('author.schedule')::uuid and not published),'Draft schedule persists');
select pg_temp.ok((select count(*)=1 from public.assessment_questions where assessment_id=(select assessment_id from public.offering_assessments where id=current_setting('author.schedule')::uuid)),'Normalized question persists');
select pg_temp.ok((public.get_exam_definition(current_setting('author.schedule')::uuid)#>>'{questions,0,correctChoice}')='0','Staff key retrieved');
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',current_setting('author.schedule')::uuid,now()-interval '1 hour',pg_temp.definition())$q$,'PT409','Stale builder save denied');
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',null,null,jsonb_set(pg_temp.definition(),'{questions,0,correctChoice}','9'))$q$,'23514','Invalid late key causes rollback');
select pg_temp.ok((select count(*)=1 from public.assessments where title='Synthetic atomic builder'),'Failed creation leaves no partial assessment');
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',current_setting('author.schedule')::uuid,(public.get_exam_definition(current_setting('author.schedule')::uuid)->>'updatedAt')::timestamptz,jsonb_set(pg_temp.definition(),'{questions,0,choices}','["Only"]'))$q$,'23514','Invalid update rolls back replacement');
select pg_temp.ok((public.get_exam_definition(current_setting('author.schedule')::uuid)#>>'{questions,0,choices,0}')='Correct','Failed update preserves original choices');
select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',current_setting('author.schedule')::uuid,(public.get_exam_definition(current_setting('author.schedule')::uuid)->>'updatedAt')::timestamptz,jsonb_set(pg_temp.definition(),'{isPublished}','true'));
select pg_temp.ok((select published from public.offering_assessments where id=current_setting('author.schedule')::uuid),'Atomic publish succeeds');
reset role;select pg_temp.claim(5);set local role authenticated;
select pg_temp.denied($q$select public.get_exam_definition(current_setting('author.schedule')::uuid)$q$,'42501','Student cannot retrieve definition keys');
select public.start_assessment_attempt(current_setting('author.schedule')::uuid);
reset role;select pg_temp.claim(1);set local role authenticated;
select pg_temp.ok((public.get_exam_definition(current_setting('author.schedule')::uuid)->>'isLocked')::boolean,'Started paper is locked');
select pg_temp.denied($q$select pg_temp.legacy_save('60000000-0000-0000-0000-000000000001',current_setting('author.schedule')::uuid,(public.get_exam_definition(current_setting('author.schedule')::uuid)->>'updatedAt')::timestamptz,pg_temp.definition())$q$,'PT409','Editing used paper is denied');
reset role;
select count(*) as passed from author_checks;
rollback;
